solid #e9edef}td:first-child,th:first-child{padding-left:0}.upstream{padding:15px 18px;border:1px dashed #b3c6cc;border-radius:8px;color:#536773;font-size:14px;margin-bottom:20px}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.step{background:white;border-top:3px solid var(--teal);padding:18px;border-radius:0 0 8px 8px}.step .stepno{font-size:12px;color:var(--teal);font-weight:700}.step h3{font-size:16px;margin:9px 0}.step p{font-size:13px;color:#536773;line-height:1.8}.bands{display:flex;margin:20px 0 12px;gap:5px}.bands div{flex:1;text-align:center;background:#e9eeee;padding:10px 0;border-radius:4px;font-size:12px}.bands .alpha{background:#d2eae6;color:#036c69;font-weight:700}.bandformula{font-size:18px;font-weight:650}.foldmap{display:grid;grid-template-columns:70px repeat(5,1fr);gap:5px;font-size:11px;text-align:center;margin:20px 0 12px}.foldmap div{padding:8px 4px;background:#e5edee;border-radius:3px}.foldmap .test{background:var(--teal);color:white}.foldmap .rowname{background:none;text-align:left;color:var(--muted)}.resultmetrics{display:grid;grid-template-columns:repeat(4,1fr);margin:0 0 24px;background:white;border:1px solid var(--line);border-radius:10px}.resultmetrics div{padding:19px 22px;border-right:1px solid var(--line)}.resultmetrics div:last-child{border:0}.resultmetrics strong{font-size:29px;display:block}.resultmetrics span{font-size:12px;color:var(--muted)}.cm-head{display:flex;justify-content:space-between;align-items:start;gap:12px}.toggle{display:flex;gap:2px;background:#edf2f3;padding:3px;border-radius:6px}.toggle button{font-size:11px;border:0;border-radius:4px;padding:4px 8px;background:none;color:var(--muted)}.toggle .active{background:white;color:var(--ink);box-shadow:0 1px 4px #0001}.cm{display:grid;grid-template-columns:74px 1fr 1fr;gap:7px;margin:20px 6px 10px}.cm .label{text-align:center;align-self:center;font-size:12px}.cm .cell{text-align:center;padding:22px 8px;border-radius:6px}.cell b{font-size:30px;display:block;line-height:1.4}.cell small{font-size:11px}.correct{background:#deeeeb;color:#086f6d}.wrong{background:#faeeda;color:#ad6b29}.cm-y{font-size:12px;color:var(--muted);margin:14px 0 -6px}.people{display:grid;grid-template-columns:repeat(11,1fr);gap:7px;margin-top:20px}.person{background:white;border:1px solid var(--line);border-top:3px solid var(--tone);padding:9px 2px;border-radius:5px;text-align:center;line-height:1.5;color:var(--ink)}.person span{font-size:10px;color:var(--muted);display:block}.person b{font-size:14px;color:var(--tone)}.person:hover,.person:focus{outline:2px solid var(--teal);outline-offset:1px}.person-info{margin-top:15px;min-height:48px;font-size:13px;padding:12px 14px;background:#e9eeee;border-radius:6px}.tablewrap{max-height:380px;overflow:auto}.tablewrap th{position:sticky;top:0;background:#f4f6f5}.tinybar{display:inline-block;height:6px;width:60px;background:linear-gradient(to right,var(--teal) var(--v),#e0e8e9 var(--v));border-radius:3px;margin-right:10px;vertical-align:middle}.takeaways{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px}.takeaways article{border-top:2px solid var(--ink);padding-top:17px}.takeaways p{font-size:14px;color:#536773}.source-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;font-size:12px;line-height:1.9;color:var(--muted)}footer{padding:26px 0 34px;color:var(--muted);font-size:12px;display:flex;justify-content:space-between;gap:15px}code{font-family:Consolas,monospace;font-size:12px;background:#e8eeee;padding:2px 4px;border-radius:3px}.nowrap{white-space:nowrap}@media(max-width:900px){.hero{grid-template-columns:1fr 1fr;gap:24px}h1{font-size:36px}.grid,.grid.wide{grid-template-columns:1fr}.steps{grid-template-columns:1fr 1fr}.people{grid-template-columns:repeat(7,1fr)}.takeaways{gap:14px}.hero-score .value{font-size:58px}nav{gap:16px}.funnelrow{grid-template-columns:160px 1fr 95px}}@media(max-width:600px){main{padding:0 18px}nav{padding:12px 18px;gap:14px}nav .brand{font-size:11px}nav a{display:non